/**
 * V1 API client.
 *
 * This is the single extension point for all v1 API calls.
 * Feature modules must use this client rather than scattered fetch() calls.
 * Extends the existing API client in services/api.ts for legacy routes.
 */

const apiBaseUrl = import.meta.env.VITE_API_BASE_URL ?? 'http://localhost:8000'
const V1_BASE = `${apiBaseUrl}/api/v1`

import type {
  CapabilityReport,
  FilePage,
  GitHubImportRequest,
  Graph,
  ImportAccepted,
  IntegrationSlotResponse,
  Snapshot,
  SourceSlice,
} from '../types/v1'

// ── Error handling ─────────────────────────────────────────────────────────

export class ApiError extends Error {
  constructor(
    public readonly status: number,
    message: string,
    public readonly code?: string,
  ) {
    super(message)
    this.name = 'ApiError'
  }
}

async function handleResponse<T>(res: Response): Promise<T> {
  if (res.ok) {
    return res.json() as Promise<T>
  }
  let message = `API returned ${res.status}`
  let code: string | undefined
  try {
    const payload: unknown = await res.json()
    if (typeof payload === 'object' && payload !== null) {
      const p = payload as Record<string, unknown>
      if ('detail' in p && typeof p.detail === 'string') message = p.detail
      if ('error' in p && typeof p.error === 'object' && p.error !== null) {
        const e = p.error as Record<string, unknown>
        if (typeof e.message === 'string') message = e.message
        if (typeof e.code === 'string') code = e.code
      }
    }
  } catch {
    // ignore parse errors
  }
  throw new ApiError(res.status, message, code)
}

// ── Imports ────────────────────────────────────────────────────────────────

export async function importZip(file: File): Promise<ImportAccepted> {
  const form = new FormData()
  form.append('file', file)
  const res = await fetch(`${V1_BASE}/imports/zip`, { method: 'POST', body: form })
  return handleResponse<ImportAccepted>(res)
}

export async function importGitHub(req: GitHubImportRequest): Promise<ImportAccepted> {
  const res = await fetch(`${V1_BASE}/imports/github`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(req),
  })
  return handleResponse<ImportAccepted>(res)
}

// ── Snapshots ──────────────────────────────────────────────────────────────

export async function listSnapshots(projectId: string): Promise<Snapshot[]> {
  const res = await fetch(`${V1_BASE}/projects/${encodeURIComponent(projectId)}/snapshots`)
  return handleResponse<Snapshot[]>(res)
}

export async function getSnapshot(projectId: string, snapshotId: string): Promise<Snapshot> {
  const res = await fetch(
    `${V1_BASE}/projects/${encodeURIComponent(projectId)}/snapshots/${encodeURIComponent(snapshotId)}`,
  )
  return handleResponse<Snapshot>(res)
}

// ── File inventory ─────────────────────────────────────────────────────────

export async function getInventory(
  projectId: string,
  snapshotId: string,
  cursor?: string,
  limit = 500,
): Promise<FilePage> {
  const params = new URLSearchParams({ limit: String(limit) })
  if (cursor) params.set('cursor', cursor)
  const res = await fetch(
    `${V1_BASE}/projects/${encodeURIComponent(projectId)}/snapshots/${encodeURIComponent(snapshotId)}/files?${params}`,
  )
  return handleResponse<FilePage>(res)
}

/** Fetch all file records across pages */
export async function getAllFiles(projectId: string, snapshotId: string): Promise<FilePage['files']> {
  const all: FilePage['files'] = []
  let cursor: string | undefined
  do {
    const page = await getInventory(projectId, snapshotId, cursor)
    all.push(...page.files)
    cursor = page.cursor ?? undefined
  } while (cursor)
  return all
}

// ── Source viewer ──────────────────────────────────────────────────────────

export async function getSource(
  projectId: string,
  snapshotId: string,
  fileId: string,
  lineStart = 1,
  lineEnd?: number,
  maxLines = 500,
): Promise<SourceSlice> {
  const params = new URLSearchParams({ line_start: String(lineStart), max_lines: String(maxLines) })
  if (lineEnd !== undefined) params.set('line_end', String(lineEnd))
  const res = await fetch(
    `${V1_BASE}/projects/${encodeURIComponent(projectId)}/snapshots/${encodeURIComponent(snapshotId)}/source/${encodeURIComponent(fileId)}?${params}`,
  )
  return handleResponse<SourceSlice>(res)
}

// ── Capabilities ───────────────────────────────────────────────────────────

export async function getCapabilities(projectId: string, snapshotId: string): Promise<CapabilityReport> {
  const res = await fetch(
    `${V1_BASE}/projects/${encodeURIComponent(projectId)}/snapshots/${encodeURIComponent(snapshotId)}/capabilities`,
  )
  return handleResponse<CapabilityReport>(res)
}

// ── Graph ──────────────────────────────────────────────────────────────────

export async function getGraph(
  projectId: string,
  snapshotId: string,
  maxEntities = 250,
): Promise<Graph> {
  const res = await fetch(
    `${V1_BASE}/projects/${encodeURIComponent(projectId)}/snapshots/${encodeURIComponent(snapshotId)}/graph?max_entities=${maxEntities}`,
  )
  return handleResponse<Graph>(res)
}

// ── Integration slot endpoints ─────────────────────────────────────────────

export async function getSlot(
  projectId: string,
  snapshotId: string,
  slot: 'summaries' | 'dependencies' | 'ask',
): Promise<IntegrationSlotResponse> {
  const res = await fetch(
    `${V1_BASE}/projects/${encodeURIComponent(projectId)}/snapshots/${encodeURIComponent(snapshotId)}/${slot}`,
  )
  return handleResponse<IntegrationSlotResponse>(res)
}

export async function getOpportunitiesSlot(
  projectId: string,
  snapshotId: string,
  kind: 'reuse' | 'duplicates' | 'unused',
): Promise<IntegrationSlotResponse> {
  const res = await fetch(
    `${V1_BASE}/projects/${encodeURIComponent(projectId)}/snapshots/${encodeURIComponent(snapshotId)}/findings/${kind}`,
  )
  return handleResponse<IntegrationSlotResponse>(res)
}

